// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));

        vm.prank(caller1);
        address owner1 = c.owner();

        vm.prank(caller2);
        address owner2 = c.owner();

        assertTrue(owner1 == owner2);
    }
}
